	title 'Tool Locator--TextState'*****************************************************************			   **	   TextState		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1988,1991	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ******************************************************************* 6-Jun-91 Dave Lyons** Text page 1 shadowing state (from bit 0 of $E0C035) is now* stored in bit 0 of the s_80col byte in the Text State handle.* SaveTextState saves the status and enables shadowing;* RestoreTextState restores the old state.** RestoreTextState(NIL) now does nothing.*****************************************************************	blanks off	string asis	print push	print off	include 'all.macros'	include '::sys.equs.asm'	INCLUDE 'e16.memory'	include 'tl.equates.asm'	print pop	title ' Imported Addresses';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT EndCall4	IMPORT EndCall8	IMPORT ErrOut4	IMPORT ErrOut8	IMPORT oBusyErr4	IMPORT oEndCall0	eject*****************************************************************SaveTextState	PROC EXPORT** Saves the text screen and releated variables into a buffer* obtained from the memory manager.  Returns handle to buffer.* * Inputs:*	none** Outputs:*	StateHandle : long** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackOrigDirect	WORDStatePtr	LONGRTL1	BLOCK 3RTL2	BLOCK 3StateHandle	LONG	pha	; push 4 bytes on to use as	pha	; StatePtr	phd	tsc	tcd	phb	; save data bank	pea $E0E0	; set it to bank e0	plb	plb; Get Memory;	pha;	pha;	PushLong #SizeStateRecord;	PushWord #TLUserID;	PushWord #$0000;	PushLong #0;	_NewHandle*** Optimized 6-Jun-91 DAL	pha	pha	;space for NewHandle	lda #0	pha	;high word of size=0	pea SizeStateRecord	;low word of size	pea TLUserID	;ID=$9001	pea $8000	;attributes=locked	pha	pha	;location doesn't matter	_NewHandle*** end 6-Jun-91 DAL	bcc NoMemError	plx	plx	tax	; put error in x	brl GetOutNowNoMemError	pla	sta StateHandle	pla	sta StateHandle+2	lda [StateHandle]	sta StatePtr	ldy #2	lda [StateHandle],y	sta StatePtr+2; Now save important zero page information relating to; state of firmware.	sep #$30	longa off	longi off; Make sure that main memory, etc is set correctly.	lda |statereg	; get memory state;;;;;	ldy #s_statereg	; put into memory block;;;;;	sta [StatePtr],y	sta [StatePtr]	;optimized 6-Jun-91 DAL; Save the video mode softswitches.	lda |rd80col*** added 6-Jun-91 DAL -- hide the text shadow state in bit 0	lsr a	pha	lda >$E0c035	lsr a	;shadow state in Carry	php	asl a	sta >$E0C035	;force text shadowing on	plp	pla	rol a	;put shadow state in bit 0*** end of 6-Jun-91 DAL	ldy #s_80Col	sta [StatePtr],y	lda |newvideo	ldy #s_NewVideo	sta [StatePtr],y;----------------------------------------------------------;; Note that we take	advantage of the fact that these next; six soft switches	line up just right and can be read; two at a time.  (We also made sure that they lined up; in the state record too.)	rep #$30	longa on	longi on	lda |rdtext	;save rdtext and rdmix	ldy #s_text	sta [StatePtr],y	lda |rdpage2	;save rdpage2 and rdhires	ldy #s_Page2	sta [StatePtr],y	lda |altcharset	;save altcharset and rd80vid	ldy #s_altCharSet	sta [StatePtr],y;----------------------------------------------------------;; I don't know why this one is a word, but it is!	lda >cursor	ldy #s_Cursor	sta [StatePtr],y;----------------------------------------------------------;; Note that I go into mixed mode here--long index but short; memory.	sep #%00100000	longa off	lda |rdc3rom	ldy #s_c3rom	sta [StatePtr],y;----------------------------------------------------------;; Back to full 16 bit mode!;	rep #%00100000	longa on;----------------------------------------------------------;; Now we save All of zero page!!!!;	ldx #0	ldy #s_ZeroPageZPLoop	lda >0,x	sta [StatePtr],y	iny	iny	inx	inx	cpx #256	bcc ZPLoop;----------------------------------------------------------;; Now we set the video to be the way we	want it!;	sep #$30	longa off	longi off	lda |newvideo	and #%01111111	sta |newvideo	sta |txtset	sta |mixclr	sta |txtpage1;----------------------------------------------------------;; Set Normal video (not inverse/flash);	lda #$FF	sta >$000032	; inverse switch;----------------------------------------------------------;; Back to full native to get the text tool global variables;	rep #$30	longa on	longi on	pha	; Start with output	device	pha	pha	_GetOutputDevice	ldy #s_OutputDevice	pla	sta [StatePtr],y	iny	iny	pla	sta [StatePtr],y	iny	iny	pla	sta [StatePtr],y	pha	; now the output globals	pha	_GetOutGlobals	ldy #s_OutGlobals	pla	sta [StatePtr],y	pla	iny	iny	sta [StatePtr],y	pha	; Next the input device	pha	pha	_GetInputDevice	ldy #s_InputDevice	pla	sta [StatePtr],y	iny	iny	pla	sta [StatePtr],y	iny	iny	pla	sta [StatePtr],y	pha	; finally, the intput globals too	pha	_GetInGlobals	ldy #s_InGlobals	pla	sta [StatePtr],y	iny	iny	pla	sta [StatePtr],y;----------------------------------------------------------;; Finally, we save the screen contents.;; Note that I save the entire screen including screen; holes.  But I carefully refrain from putting back; any of the screen	holes except for slot 3.;	jsl SaveTheScreen*** added 6-Jun-91 DAL -- unlock the state handle	ldy #4	lda [<StateHandle],y	and #$7fff	sta [<StateHandle],y*** end of 6-Jun-91 DAL	ldx #0	; signal no errorGetOutNow	plb	; restore the data bank	pld	; restore direct page reg	pla	; get rid of pointer	pla	txa	cmp #1	rtl;----------------------------------------------------------;; SaveTheScreen;SaveTheScreen	ldx #0	ldy #s_TextBank0B0Loop	lda >$000400,x	sta [StatePtr],y	iny	iny	inx	inx	cpx #$400	bcc B0Loop	ldx #0	ldy #s_TextBank1B1Loop	lda >$010400,x	sta [StatePtr],y	iny	iny	inx	inx	cpx #$400	bcc B1Loop	ldx #0	ldy #s_TextBankE0BE0Loop	lda >$E00400,x	sta [StatePtr],y	iny	iny	inx	inx	cpx #$400	bcc BE0Loop	ldx #0	ldy #s_TextBankE1BE1Loop	lda >$E10400,x	sta [StatePtr],y	iny	iny	inx	inx	cpx #$400	bcc BE1Loop	rtl	ENDP*****************************************************************RestoreTextState	PROC EXPORT** Restores text screen and related variables from handle * passed by user.  (Handle should have been created by SaveTextState* call.)  Disposes of handle.*** Inputs:*	ScreenDataHandle : long** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackOrigDirect	WORDStatePtr	LONGRTL1	BLOCK 3RTL2	BLOCK 3StateHandle	LONG	pha	; push 4 bytes on to use as	pha	; StatePtr	phd	tsc	tcd	phb	; save data bank	pea $E0E0	; set it to bank e0	plb	plb*** added 6-Jun-91 DAL -- if StateHandle=NIL, take no action	lda <StateHandle+1	bne @continue	ldx #0	brl ExitRestTextState@continue	ldy #4	lda [StateHandle],y	ora #$8000	sta [StateHandle],y*** end of 6-Jun-91 DAL;----------------------------------------------------------;; Dereference the state record handle.;	lda [StateHandle]	sta StatePtr	ldy #2	lda [StateHandle],y	sta StatePtr+2; Now save important zero page information relating to; state of firmware.	sep #$30	longa off	longi off; Now the video mode switches	ldy #s_80Col*** added 6-Jun-91 DAL -- restore text shadow state from bit 0	lda [StatePtr],y	lsr a	;shadow state in Carry	php	lda >$e0c035	lsr a	plp	;shadow state in Carry again	rol a	sta >$e0c035*** end 6-Jun-91 DAL	lda [StatePtr],y	bpl Clear80Col	sta |Set80Col	bra Done80ColClear80Col	sta |Clr80ColDone80Col		; 	ldy #s_80Vid	lda [StatePtr],y	bpl Clear80Vid	sta |Set80Vid	bra Done80VidClear80Vid	sta |Clr80VidDone80Vid		; 	ldy #s_NewVideo	; new video	lda [StatePtr],y	and #$C0	ora |newvideo	sta |newvideo	ldy #s_text	; text	lda [StatePtr],y	bpl ClearText	sta |txtset	bra DoneTextClearText	sta |txtclrDoneText		; 	ldy #s_mix	; text mix	lda [StatePtr],y	bpl ClearMix	sta |MixSet	bra DoneMixClearMix	sta |MixClrDoneMix		; 	ldy #s_Page2	; page 2	lda [StatePtr],y	bpl DoPage1	sta |TxtPage2	bra DonePageDoPage1	sta |TxtPage1DonePage		; 	ldy #s_Hires	; hires	lda [StatePtr],y	bpl DoLoRes	sta |hires	bra DoneHiresDoLoRes	sta |loresDoneHires		; 	ldy #s_altCharSet	; alternate character set.	lda [StatePtr],y	bpl ClearAC	sta |setaltchar	bra DoneAltCharClearAC	sta |ClrAltCharDoneAltChar		; 	sta |altcharset	ldy #s_c3rom	; slot 3 rom	lda [StatePtr],y	bpl DoInternal	sta |setslotc3rom	bra DoneSlot3DoInternal	sta |setintc3romDoneSlot3		; ;----------------------------------------------------------;; Retore the State register;;;;;;	ldy #s_statereg;;;;;	lda [StatePtr],y	lda [StatePtr]	;optimized 6-Jun-91 DAL	sta |statereg	rep #$30	longa on	longi on;----------------------------------------------------------;; I don't know why this one is a word, but it is!	ldy #s_Cursor	lda [StatePtr],y	sta >cursor;----------------------------------------------------------;; Now we restore All of zero page!!!!;	ldx #0	ldy #s_ZeroPageZPLoop	lda [StatePtr],y	sta >0,x	iny	iny	inx	inx	cpx #256	bcc ZPLoop;----------------------------------------------------------;; Back to full native to get the text tool global variables;	rep #$30	longa on	longi on	ldy #s_OutputDevice+4	lda [StatePtr],y	pha	dey	dey	lda [StatePtr],y	pha	dey	dey	lda [StatePtr],y	pha	_SetOutputDevice	ldy #s_OutGlobals+2	lda [StatePtr],y	pha	dey	dey	lda [StatePtr],y	pha	_SetOutGlobals	ldy #s_InputDevice+4	lda [StatePtr],y	pha	dey	dey	lda [StatePtr],y	pha	dey	dey	lda [StatePtr],y	pha	_SetInputDevice	ldy #s_InGlobals+2	lda [StatePtr],y	pha	dey	dey	lda [StatePtr],y	pha	; now the output globals	_SetInGlobals;----------------------------------------------------------;; Finally, we restore the screen contents.;; Note that I save the current screen holes on the stack; restore the entire screen and then restore the screen; holes.;	php	; save int state	sei	; off the ints!	jsr SaveScreenHoles	jsl RepTheScreen	jsr RestoreScreenHoles	plp	; restore int state!	pei StateHandle+2	pei StateHandle	_DisposeHandle	taxExitRestTextState	plb	; restore the data bank	pld	; restore direct page reg	pla	; get rid of pointer	pla	ldy #4	jml ToStrip;----------------------------------------------------------;; RepTheScreen;RepTheScreen	ldx #0	ldy #s_TextBank0B0Loop	lda [StatePtr],y	sta >$000400,x	iny	iny	inx	inx	cpx #$400	bcc B0Loop	ldx #0	ldy #s_TextBank1B1Loop	lda [StatePtr],y	sta >$010400,x	iny	iny	inx	inx	cpx #$400	bcc B1Loop	ldx #0	ldy #s_TextBankE0BE0Loop	lda [StatePtr],y	sta >$E00400,x	iny	iny	inx	inx	cpx #$400	bcc BE0Loop	ldx #0	ldy #s_TextBankE1BE1Loop	lda [StatePtr],y	sta >$E10400,x	iny	iny	inx	inx	cpx #$400	bcc BE1Loop	rtl;----------------------------------------------------------;; Routines to save and restore screen holes;SaveScreenHoles		; 	ply	; get rts address off stack; Warning: mixed mode again!!!!	sep #%00100000	longa off	ldx #1	; start with slot 1SaveLoop		; 	cpx #3	beq Skip3Save	lda >$000478,x	pha	lda >$0004F8,x	pha	lda >$000578,x	pha	lda >$0005F8,x	pha	lda >$000678,x	pha	lda >$0006F8,x	pha	lda >$000778,x	pha	lda >$0007F8,x	phaSkip3Save	inx	cpx #8	bcc SaveLoop	rep #$30	; put rts adr back on the stack	longa on	longi on	phy	rtsRestoreScreenHoles		; 	ply	; get rts address off stack; Warning: mixed mode again!!!!	sep #%00100000	longa off	ldx #7	; start with slot 7	when restoreingRepLoop		; 	cpx #3	beq Skip3Rep	pla	sta >$0007F8,x	pla	sta >$000778,x	pla	sta >$0006F8,x	pla	sta >$000678,x	pla	sta >$0005F8,x	pla	sta >$000578,x	pla	sta >$0004F8,x	pla	sta >$000478,xSkip3Rep	dex	bne RepLoop	rep #$30	; put rts adr back on the stack	longa on	longi on	phy	rts	ENDP	END